package app.shiori.dict

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.boolean
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive

data class Deinflection(val text: String, val rules: Set<String>, val reasons: List<String>)

/**
 * Port of Yomitan's LanguageTransformer (ext/js/language/language-transformer.js) driven by the
 * data in japanese-transforms.json (generated by scripts/gen-transforms.mjs).
 * Conditions are bit flags; a condition with subConditions is the union of theirs.
 */
class Deinflector(transformsJson: String) {
    private class Rule(
        val whole: Boolean,
        val inflected: String,
        val deinflected: String,
        val outNames: Set<String>,
        val conditionsIn: Long,
        val conditionsOut: Long,
    )

    private class Transform(val id: String, val name: String, val rules: List<Rule>)

    private class Frame(val transform: Transform, val ruleIndex: Int, val text: String)

    private class Item(val text: String, val conditions: Long, val outNames: Set<String>, val trace: List<Frame>)

    private val conditionFlags = HashMap<String, Long>()
    private val partOfSpeechFlags = HashMap<String, Long>()
    private val transforms: List<Transform>

    init {
        val root = Json.parseToJsonElement(transformsJson).jsonObject
        val conds = root.getValue("conditions").jsonObject
        var next = 0
        var pending = conds.entries.toList()
        while (pending.isNotEmpty()) {
            val rest = ArrayList<Map.Entry<String, JsonElement>>()
            for (e in pending) {
                val subs = names(e.value.jsonObject.getValue("subConditions"))
                if (subs.isEmpty()) {
                    check(next < 63) { "too many conditions" }
                    conditionFlags[e.key] = 1L shl next++
                } else if (subs.all { it in conditionFlags }) {
                    conditionFlags[e.key] = subs.fold(0L) { a, s -> a or conditionFlags.getValue(s) }
                } else {
                    rest.add(e)
                }
            }
            check(rest.size < pending.size) { "cycle in subConditions" }
            pending = rest
        }
        for ((name, c) in conds) {
            if (c.jsonObject.getValue("isDictionaryForm").jsonPrimitive.boolean) partOfSpeechFlags[name] = conditionFlags.getValue(name)
        }
        transforms = root.getValue("transforms").jsonArray.map { t ->
            val o = t.jsonObject
            Transform(
                o.getValue("id").jsonPrimitive.content,
                o.getValue("name").jsonPrimitive.content,
                o.getValue("rules").jsonArray.map { r ->
                    val ro = r.jsonObject
                    val ins = names(ro.getValue("conditionsIn"))
                    val outs = names(ro.getValue("conditionsOut"))
                    Rule(
                        ro.getValue("type").jsonPrimitive.content == "wholeWord",
                        ro.getValue("inflected").jsonPrimitive.content,
                        ro.getValue("deinflected").jsonPrimitive.content,
                        outs.toSet(), flags(ins), flags(outs),
                    )
                },
            )
        }
    }

    private fun names(a: JsonElement) = a.jsonArray.map { it.jsonPrimitive.content }

    private fun flags(names: Collection<String>): Long = names.fold(0L) { a, n ->
        a or (conditionFlags[n] ?: error("unknown condition $n"))
    }

    /** Yomitan's conditionsMatch: 0 matches anything, otherwise at least one shared flag. */
    private fun match(current: Long, next: Long) = current == 0L || (current and next) != 0L

    /** Flags of a dictionary entry's rules (Yomitan getConditionFlagsFromPartsOfSpeech). */
    private fun entryFlags(entryRules: Collection<String>): Long =
        entryRules.fold(0L) { a, r -> a or (partOfSpeechFlags[r] ?: parentFlags(r)) }

    // Extension: Yomitan counts a rule name it does not know (e.g. v5k-s) as no flags. Detailed JMdict
    // names are instead treated as their dictionary-form parent (v5k-s as v5, adj-ix as adj-i).
    private fun parentFlags(rule: String): Long {
        val parent = partOfSpeechFlags.keys
            .filter { it.length >= 2 && rule.length > it.length && rule.startsWith(it) && !rule[it.length].isDigit() }
            .maxByOrNull { it.length } ?: return 0L
        return partOfSpeechFlags.getValue(parent)
    }

    /** Whether an entry with [entryRules] fits a deinflection with [deinflectionRules] (Translator._matchEntriesToDeinflections). */
    fun rulesMatch(deinflectionRules: Set<String>, entryRules: Set<String>): Boolean {
        val cur = deinflectionRules.fold(0L) { a, n -> a or (conditionFlags[n] ?: 0L) }
        return match(cur, entryFlags(entryRules))
    }

    /** Breadth-first deinflection; the first result is the source itself with empty rules. */
    fun deinflect(source: String): List<Deinflection> {
        val results = ArrayList<Item>()
        results.add(Item(source, 0L, emptySet(), emptyList()))
        var i = 0
        while (i < results.size) {
            val item = results[i++]
            if (item.trace.size >= MAX_DEPTH) continue
            val text = item.text
            for (t in transforms) {
                for ((j, rule) in t.rules.withIndex()) {
                    if (!match(item.conditions, rule.conditionsIn)) continue
                    val hit = if (rule.whole) text == rule.inflected else text.endsWith(rule.inflected)
                    if (!hit) continue
                    if (item.trace.any { it.transform === t && it.ruleIndex == j && it.text == text }) continue
                    val out = if (rule.whole) rule.deinflected else text.dropLast(rule.inflected.length) + rule.deinflected
                    results.add(Item(out, rule.conditionsOut, rule.outNames, listOf(Frame(t, j, text)) + item.trace))
                }
            }
        }
        return results.map { r -> Deinflection(r.text, r.outNames, r.trace.map { it.transform.name }) }
    }

    private companion object {
        const val MAX_DEPTH = 10
    }
}
